import{_ as a,C as o,o as d,c as n,E as s,a2 as i}from"./chunks/framework.Cm6XCzck.js";const b=JSON.parse('{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.8","description":"","frontmatter":{"title":"TMPA–FCoP–CodeFlowMu 实施案例 — 草稿 I0.8","outline":"deep","citation":{"work":"TMPA Implementation Case","identifier":"TMPA-CASE-I0.8","language":"zh","metadata":"/releases/tmpa/v1.0-rc1/metadata/implementation-case.zh.cff"}},"headers":[],"relativePath":"zh/publications/implementation-case-i0.8/part-01.md","filePath":"zh/publications/implementation-case-i0.8/part-01.md","lastUpdated":1786355271000}'),l={name:"zh/publications/implementation-case-i0.8/part-01.md"};function r(p,e,c,h,u,m){const t=o("ArticleCover");return d(),n("div",null,[s(t,{image:"/assets/covers/implementation-case.svg",kicker:"工程案例",title:"TMPA 实施案例",summary:"CodeFlowMu V1.6.0 针对 TMPA Core S0.6 精确输入的产品运行与自包含公开复现器。",version:"I0.8",status:"S0.6 产品证据草稿 · 14/14 PASS",languageHref:"/en/publications/implementation-case-i0.8",languageLabel:"English"}),e[0]||(e[0]=i(`<h1 id="tmpa-实施与案例报告" tabindex="-1">TMPA 实施与案例报告 <a class="header-anchor" href="#tmpa-实施与案例报告" aria-label="Permalink to &quot;TMPA 实施与案例报告&quot;">​</a></h1><h2 id="tmpa-core-s0-6、fcop、codeflowmu-v1-6-0-与保留的现场证据" tabindex="-1">TMPA Core S0.6、FCoP、CodeFlowMu V1.6.0 与保留的现场证据 <a class="header-anchor" href="#tmpa-core-s0-6、fcop、codeflowmu-v1-6-0-与保留的现场证据" aria-label="Permalink to &quot;TMPA Core S0.6、FCoP、CodeFlowMu V1.6.0 与保留的现场证据&quot;">​</a></h2><blockquote><p><strong>文档版本：</strong> 草稿 I0.8<br><strong>状态：</strong> 作者制作的实施与案例报告<br><strong>规范目标：</strong> <a href="/joinwell52/zh/publications/tmpa-core-specification-s0.6">TMPA Core Specification S0.6</a>，Commit <code>8989657e8fde6d2e55d7606ae0adacac14fec760</code><br><strong>受测产品：</strong> CodeFlowMu V1.6.0，实现 Commit <code>62440a526a99d2fe55019d8bb95ad2425569fcb4</code><br><strong>证据采集：</strong> 2026-08-10，Asia/Shanghai<br><strong>正式证据包：</strong> <code>tmpa-i0.8-codeflowmu-v1.6.0-s0.6-evidence-20260810.zip</code><br><strong>压缩包 SHA-256：</strong> <code>3c34514089f08f5957d806f900ab31af1cdae94c08f31a5da046f451b5884fe9</code><br><strong>权威边界：</strong> 本报告属于证据性、非规范性文档；只有 Core Specification 定义 TMPA 要求。</p></blockquote><h2 id="摘要" tabindex="-1">摘要 <a class="header-anchor" href="#摘要" aria-label="Permalink to &quot;摘要&quot;">​</a></h2><p>I0.8 使用规范仓库 Commit 固定的原始 LF 字节，对 CodeFlowMu V1.6.0 执行 TMPA Core S0.6 全部十四项强制准则。产品级结果为 <strong>14 PASS、0 PARTIAL、0 NOT RUN、0 FAIL</strong>。CodeFlowMu 产品 Runner 调用自身同步 <code>GovernanceReader</code>，不调用 TMPA Reference Reader。输入 Bundle Digest 为 <code>sha256:251914ee55922d20c9bd23943a4ff445bccaa5835e1fcc11b8562f3f384243fa</code>。</p><p>本次工程升级关闭了相对于 I0.7/S0.5 基线的 S0.6 可观察差异：字节相同的观测保留每个贡献来源 ID；高风险批准必须同时满足允许的裁决对象类型、有效角色 Assignment、允许角色、批准决定，以及 Profile 要求时相互独立的行为者；所有规范排序采用不依赖 Locale 的 Unicode 码点顺序，并包含 U+E000 与 U+10000 回归。CodeFlowMu 内置 TMPA 套件为 23/23，Runtime 为 1,485 passed / 0 failed / 1 skipped，Shell 为 777/777，锁定的 FCoP 参考实现为 1,210 passed / 2 skipped。</p><p>证据包包含自包含公开复现器。干净环境执行 <code>npm ci</code> 与 <code>npm test</code>，先核验七份正式 S0.6 文件的字节摘要，再运行 CodeFlowMu 产品 Reader，得到 14/14 PASS；复现该符合性切片不需要私有 CodeFlowMu 母体仓库。当前最强且不越界的结论仍是：<strong>固定 Bundle 下由作者运行所 demonstrated 的行为</strong>。它不是独立认证、独立采用、任意输入上的证明，也不证明 AI 幻觉已经消除。</p><h1 id="_1-范围与研究问题" tabindex="-1">1. 范围与研究问题 <a class="header-anchor" href="#_1-范围与研究问题" aria-label="Permalink to &quot;1. 范围与研究问题&quot;">​</a></h1><p>I0.8 回答：</p><ol><li>CodeFlowMu V1.6.0 产品 Reader 是否针对同一个精确、固定的输入 Bundle 满足 S0.6 C01–C14？</li><li>来源保留、完整人工批准授权和不依赖 Locale 的排序这三项 S0.6 可观察变化，是否已实现且没有破坏 I0.7 demonstrated 的 S0.5 行为？</li><li>在无法访问私有 CodeFlowMu 母体仓库时，符合性切片能否公开复跑？</li><li>哪些证据仍是作者本地运行，哪些结论仍未获得支持？</li></ol><p>裁决单位是固定 Bundle 上绑定具体准则的主张。四个证据层级严格分开：</p><table tabindex="0"><thead><tr><th>层级</th><th>I0.8 中的含义</th><th style="text-align:right;">是否达到</th></tr></thead><tbody><tr><td>Specified</td><td>由 TMPA Core S0.6 规范定义</td><td style="text-align:right;">是</td></tr><tr><td>Implemented</td><td>CodeFlowMu 中存在相应机制</td><td style="text-align:right;">是</td></tr><tr><td>Demonstrated</td><td>执行产生了可检查证据</td><td style="text-align:right;">是，仅限固定 C01–C14 Bundle</td></tr><tr><td>Independently Adopted</td><td>独立组织采用并验证该机制</td><td style="text-align:right;">否</td></tr></tbody></table><h1 id="_2-架构与证据边界" tabindex="-1">2. 架构与证据边界 <a class="header-anchor" href="#_2-架构与证据边界" aria-label="Permalink to &quot;2. 架构与证据边界&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TMPA Architecture Paper</span></span>
<span class="line"><span>        ↓ 理论指导工程方向</span></span>
<span class="line"><span>TMPA Core S0.6</span></span>
<span class="line"><span>        ↓ 固定规范对象、Reader 与符合性契约</span></span>
<span class="line"><span>FCoP 协议</span></span>
<span class="line"><span>        ↓ 提供现实协作与证据协议</span></span>
<span class="line"><span>CodeFlowMu V1.6.0 应用执行与消费层</span></span>
<span class="line"><span>        ↓ 产品 Reader、Runtime、角色、恢复与审计</span></span>
<span class="line"><span>WP-13 与其他有限案例</span></span></code></pre></div><p>TMPA 理论指导 CodeFlowMu 的工程方向，Core S0.6 固定本报告接受评估的规范行为。FCoP 是 CodeFlowMu 使用的现实协作与证据协议，不是应用程序；<code>fcop</code> 与 <code>fcop-mcp</code> 是参考实现，不等于协议本身。按照 CodeFlowMu 工程架构 [7]，CodeFlowMu 是应用执行与消费层：负责产生协作事实、运行 Adapter 与 Reader、投影治理图，并让恢复与治理门禁消费重建结果。WP-13 保留为有界的证据准入案例；小典 AI 仅作为作者报告的工程谱系，不纳入评估证据；二者都不能替代 S0.6 产品运行。</p><p>概念依赖与历史形成过程保持分离：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>当前指导：TMPA 理论 → Core 要求 → FCoP 协议</span></span>
<span class="line"><span>                                  → CodeFlowMu 工程落实</span></span>
<span class="line"><span>历史反馈：小典实践 → 早期 TMPA → FCoP 提取</span></span>
<span class="line"><span>                               → CodeFlowMu 工程实现</span></span>
<span class="line"><span>FCoP + CodeFlowMu 结果 → 当前 TMPA 形式化</span></span></code></pre></div><p>历史反馈解释理论如何成熟，但不会倒置当前权威关系。产品行为可以提供证据或推动后续修订，却不能重定义当前 Core。</p><h1 id="_3-锁定来源与证据设计" tabindex="-1">3. 锁定来源与证据设计 <a class="header-anchor" href="#_3-锁定来源与证据设计" aria-label="Permalink to &quot;3. 锁定来源与证据设计&quot;">​</a></h1><table tabindex="0"><thead><tr><th>来源</th><th>锁定标识</th><th>I0.8 中的作用</th><th>边界</th></tr></thead><tbody><tr><td>TMPA Core</td><td>S0.6，Commit <code>8989657…</code></td><td>C01–C14 规范目标</td><td>规范，不是产品证据</td></tr><tr><td>CodeFlowMu</td><td>V1.6.0，Commit <code>62440a5…</code></td><td>受测产品实现</td><td>本地实现 Commit，不表述为公开 Release</td></tr><tr><td>公开复现器</td><td>29 个锁定文件</td><td>公开复跑符合性切片</td><td>不公开或复现整个私有产品</td></tr><tr><td>FCoP 参考实现</td><td>Commit <code>da79dfe…</code></td><td>锁定依赖基线</td><td>测试结果不是抽象协议证明</td></tr><tr><td>I0.7</td><td>S0.5 / CodeFlowMu V1.4.1</td><td>历史回归基线</td><td>保留精确的旧版含义</td></tr><tr><td>WP-13 V3</td><td>已出版证据包</td><td>证据门禁现场案例</td><td>未复跑，也未提升为符合性证明</td></tr></tbody></table><p>七份正式 S0.6 输入——四份 Schema、规范化 Profile、生命周期 Profile 与 Fixture——均与 GitHub 字节完全一致。第一次提交的压缩包包含 Windows Checkout 转换后的 CRLF 副本，出版预检拒绝了该包。最终包使用 Git 原始 Blob 字节重新运行产品准则，并重新生成全部关联 Digest，而不是修改旧结果 JSON。</p>`,21))])}const g=a(l,[["render",r]]);export{b as __pageData,g as default};
